**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int px[100], py[100];
    double dist[100];
    for (int i = 0; i < n; i++) {
        plik >> px[i] >> py[i];
        dist[i] = sqrt((double)(px[i] * px[i] + py[i] * py[i]));
    }
    cout << fixed << setprecision(2);
    int minIdx = 0, maxIdx = 0;
    for (int i = 0; i < n; i++) {
        cout << "(" << px[i] << "," << py[i] << "): " << dist[i] << endl;
        if (dist[i] < dist[minIdx]) minIdx = i;
        if (dist[i] > dist[maxIdx]) maxIdx = i;
    }
    cout << "Najblizszy: (" << px[minIdx] << "," << py[minIdx] << "), odleglosc = " << dist[minIdx] << endl;
    cout << "Najdalszy: (" << px[maxIdx] << "," << py[maxIdx] << "), odleglosc = " << dist[maxIdx] << endl;
    return 0;
}
```

**Wyjasnienie**: Odleglosc od poczatku ukladu (0,0) to sqrt(x^2 + y^2). Sledzac min i max w jednym przebiegu, znajdujemy punkt najblizszy i najdalszy.

Weryfikacja:
- (3,4): sqrt(9+16) = sqrt(25) = 5.00
- (1,1): sqrt(1+1) = sqrt(2) = 1.41
- (5,0): sqrt(25+0) = 5.00
- (0,2): sqrt(0+4) = 2.00
- (4,3): sqrt(16+9) = sqrt(25) = 5.00
- (2,7): sqrt(4+49) = sqrt(53) = 7.28
- (6,1): sqrt(36+1) = sqrt(37) = 6.08
Min: (1,1) = 1.41, Max: (2,7) = 7.28.
